-- Dates are relative to the day the seed runs so "This Month" and "Todays
-- Recordings" derive from the rows: four logs land in the current month (on or
-- before today), the other seven in the previous month.
with p as (
  select
    (date_trunc('month', current_date)::date
      + least(extract(day from current_date)::int - 1, 3)) as anchor,
    (date_trunc('month', current_date) - interval '1 month')::date + 4 as prev_month
),
v (id, employee_id, field_id, activity_type_id, this_month, day_offset, start_time, end_time, status) as (
  values
    ('00000000-0000-4000-8000-100000000001'::uuid, '00000000-0000-4000-8000-e00000000001'::uuid, '00000000-0000-4000-8000-f00000000001'::uuid, '00000000-0000-4000-8000-a00000000001'::uuid, true, 3, time '06:00', time '10:40', 'new'::public.log_status),
