insert into public.activity_logs (id, org_id, employee_id, field_id, activity_type_id, started_at, ended_at, status, created_at)
select
  v.id, '00000000-0000-4000-8000-000000000001', v.employee_id, v.field_id, v.activity_type_id,
  (case when v.this_month then p.anchor - v.day_offset else p.prev_month + v.day_offset end + v.start_time)::timestamptz,
  (case when v.this_month then p.anchor - v.day_offset else p.prev_month + v.day_offset end + v.end_time)::timestamptz,
  v.status,
  now() + (v.day_offset || ' milliseconds')::interval
from p, v;

-- Five recordings are stamped today so "Todays Recordings" reads 5; the rest
-- were dictated at the end of the shift they describe. Confidences average
-- exactly 0.90.
