insert into public.recordings (log_id, duration_seconds, recorded_at, transcript, transcription_confidence, waveform, map_pin)
select
  v.log_id, v.duration_seconds,
  case when v.today then (current_date + l.ended_at::time)::timestamptz else l.ended_at end,
  v.transcript, v.transcription_confidence, v.waveform, v.map_pin
from v
join public.activity_logs l on l.id = v.log_id;

-- ---------------------------------------------------------------------------
-- What the crew actually said, and what the extractor made of it.
--
-- Applied as an update rather than inline above so the waveform arrays — which
-- are generated from real audio — stay where they are and this stays readable.
--
-- The transcripts are the demo. A compliance manager opening a log reads these
-- words before anything else, and until they were written the most important
-- content in the product was the ingestion harness's own scaffolding
-- ("Question (activity_type): What type of activity was this...") — which is
-- not a thing any farm worker has ever said.
--
-- Three details are deliberate:
--
--   * Isaac Wang's is degraded, with [inaudible] where the wind took the words.
--     That is why his transcription confidence is 0.62, why the extractor got
--     no product or rate out of it, and why his log is the one missing its
--     compliance record. One cause, visible in four places.
--   * Ethan Kim says he ran out before the far end and never measured the area,
--     which is exactly why his record is filed but incomplete.
--   * Two logs are in Spanish, because most people doing crop work in the US
--     speak it. `transcript` stays in the language it was spoken — that is the
--     record an inspector is entitled to — and `transcript_en` carries the
--     English for whoever is reading the dashboard.
-- ---------------------------------------------------------------------------
update public.recordings r
set transcript = v.spoken, transcript_en = v.english, language = v.lang,
    extracted_fields = v.extracted::jsonb
from (values
  ('00000000-0000-4000-8000-100000000001'::uuid,
   'Okay this is Isaac, uh, I''m on Field A, we just finished the — [inaudible] — the spray on the north half. Wind picked up around [inaudible] so we stopped early. I''ll have to check the jug for the — [inaudible] — I didn''t write the rate down.',
   null, 'en',
   '{"activityType":{"value":"Spraying","confidence":0.88},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD A","confidence":0.93},"weather":{"value":"Wind rising, speed not stated","confidence":0.42}}'),
  ('00000000-0000-4000-8000-100000000002'::uuid,
   'Maya here. Finished picking Field B, the whole block. Started half seven, wrapped up around quarter past eleven. Good yield on the east rows, the west side is still a week out I''d say.',
   null, 'en',
   '{"activityType":{"value":"Harvesting","confidence":0.97},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD B","confidence":0.99},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000003'::uuid,
   'Liam, Field C. Got the transplants in across the whole block today, eight in the morning through noon. Soil was still a bit wet from Tuesday so we went slower than planned but they''re all in the ground.',
   null, 'en',
   '{"activityType":{"value":"Planting","confidence":0.96},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD C","confidence":0.98},"weather":{"value":"Soil wet from recent rain","confidence":0.71}}'),
  ('00000000-0000-4000-8000-100000000004'::uuid,
   'Sophia. Ran irrigation on Field D this morning, six thirty to about nine thirty. Line four had a slow emitter near the south corner, I flagged it, someone should look at it before the next set.',
   null, 'en',
   '{"activityType":{"value":"Irrigation","confidence":0.95},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD D","confidence":0.97},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000005'::uuid,
   'Ethan, Field E. Side-dressed with urea at the usual rate, about a hundred and twenty pounds per acre. Spreader was calibrated this morning. I didn''t measure how much of the block we covered, we ran out before the far end.',
   null, 'en',
   '{"activityType":{"value":"Fertilizing","confidence":0.96},"product":{"value":"Urea 46-0-0","confidence":0.93},"rate":{"value":"120 lb/acre","confidence":0.9},"field":{"value":"FIELD E","confidence":0.98},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000006'::uuid,
   'Soy Olivia. Estuve desyerbando el Campo F toda la mañana, desde las seis y cuarto hasta las diez. La hierba está peor en la orilla del canal, por allá hay que volver la próxima semana.',
   'This is Olivia. I was weeding Field F all morning, from six fifteen until ten. The weeds are worst along the edge of the ditch — we need to go back there next week.', 'es',
   '{"activityType":{"value":"Weeding","confidence":0.94},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD F","confidence":0.96},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000007'::uuid,
   'Noah, Field G. Pruning all morning, seven to half eleven. Took out the dead wood on the older rows. There''s some canker on maybe six or seven trees at the top of the block, worth having someone look.',
   null, 'en',
   '{"activityType":{"value":"Pruning","confidence":0.95},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD G","confidence":0.97},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000008'::uuid,
   'Emma. Scouting Field H, eight fifteen through to about quarter to one. Counted aphids on the lower leaves, maybe five or six per plant on the south end, nothing on the north. Not at threshold yet but I''d check again in three days.',
   null, 'en',
   '{"activityType":{"value":"Monitoring","confidence":0.97},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD H","confidence":0.98},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000009'::uuid,
   'James Wilson, soil sampling on Field I. Six to nine. Pulled cores from twelve spots across the block, bagged and labelled them. They''re in the shop fridge ready to go to the lab Monday.',
   null, 'en',
   '{"activityType":{"value":"Soil Testing","confidence":0.96},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD I","confidence":0.98},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000010'::uuid,
   'Habla Isabella. Terminé de sembrar el Campo J, empecé a las ocho menos cuarto y acabé como a las once. La sembradora se atascó dos veces en la parte de arriba donde la tierra está más dura.',
   'This is Isabella. I finished seeding Field J — I started at quarter to eight and finished around eleven. The seeder jammed twice at the top end where the ground is harder.', 'es',
   '{"activityType":{"value":"Seeding","confidence":0.92},"product":{"value":null,"confidence":null},"rate":{"value":null,"confidence":null},"field":{"value":"FIELD J","confidence":0.95},"weather":{"value":null,"confidence":null}}'),
  ('00000000-0000-4000-8000-100000000011'::uuid,
   'Benjamin, Field K. Pest control pass across eighteen acres. Ran Spinosad at half a gallon an acre and sulfur at five pounds an acre in the same tank. Wind was light, about three, temperature around seventy. Started six thirty, off by half ten.',
   null, 'en',
   '{"activityType":{"value":"Pest Control","confidence":0.98},"product":{"value":"Spinosad 480SC, Sulfur DF","confidence":0.94},"rate":{"value":"0.5 gal/acre, 5 lb/acre","confidence":0.91},"field":{"value":"FIELD K","confidence":0.99},"weather":{"value":"Wind 3 mph, 70 °F","confidence":0.89}}')
) as v(log_id, spoken, english, lang, extracted)
where r.log_id = v.log_id;

-- Starter tags for "Add Tag". A small vocabulary rather than none, so the
-- picker's fast path (choose an existing tag) is the one you meet first; new
-- names typed into the picker are created alongside these.
insert into public.tags (org_id, name) values
  ('00000000-0000-4000-8000-000000000001', 'Follow up'),
  ('00000000-0000-4000-8000-000000000001', 'Chemical applied'),
  ('00000000-0000-4000-8000-000000000001', 'Equipment issue'),
  ('00000000-0000-4000-8000-000000000001', 'Weather delay'),
  ('00000000-0000-4000-8000-000000000001', 'Verified')
on conflict (org_id, name) do nothing;

-- ---------------------------------------------------------------------------
-- The product register, and what was actually applied.
--
-- Each application matches what its log's transcript says, so the compliance
-- record and the worker's own words agree — including where they fall short.
-- The three states the Audit Manager exists to tell apart are all present:
--
--   log ...0011  Pest Control   two products, area and conditions  -> complete
--   log ...0005  Fertilizing    rate but no treated area           -> incomplete
--   log ...0001  Spraying       nothing at all                     -> missing
--
-- The last is not an oversight in the seed. That log's recording is the
-- 0.62-confidence one whose transcript came back as "I'm leaving first, I'm
-- going to go home" — a voice log that yielded neither an activity nor a
-- product should not have produced a record, and finding it is the job.
-- ---------------------------------------------------------------------------
insert into public.products (id, org_id, name, kind, epa_registration, active_ingredient, rate_unit, rei_hours, phi_days) values
  ('00000000-0000-4000-8000-b00000000001', '00000000-0000-4000-8000-000000000001', 'Spinosad 480SC',           'chemical',   '62719-291', 'Spinosad',          'gal/acre', 4,    7),
  ('00000000-0000-4000-8000-b00000000002', '00000000-0000-4000-8000-000000000001', 'Sulfur DF',                'chemical',   '70051-75',  'Sulfur',            'lb/acre',  24,   0),
  ('00000000-0000-4000-8000-b00000000003', '00000000-0000-4000-8000-000000000001', 'Glyphosate 41%',           'chemical',   '524-537',   'Glyphosate',        'gal/acre', 12,   14),
  ('00000000-0000-4000-8000-b00000000004', '00000000-0000-4000-8000-000000000001', 'Urea 46-0-0',              'fertilizer', null,        'Nitrogen (urea)',   'lb/acre',  null, null),
  ('00000000-0000-4000-8000-b00000000005', '00000000-0000-4000-8000-000000000001', 'Calcium Nitrate 15.5-0-0', 'fertilizer', null,        'Nitrogen, Calcium', 'lb/acre',  null, null),
  ('00000000-0000-4000-8000-b00000000006', '00000000-0000-4000-8000-000000000001', 'Compost, Class A',         'amendment',  null,        'Organic matter',    'ton/acre', null, null)
on conflict (id) do nothing;

insert into public.applications (log_id, product_id, rate, area_acres, wind_speed_mph, air_temp_f) values
  -- "about a hundred and twenty pounds per acre" — the transcript gives the rate
  -- but never the treated area, so the record exists and is incomplete.
  ('00000000-0000-4000-8000-100000000005', '00000000-0000-4000-8000-b00000000004', 120.000, null,  null, null),
  ('00000000-0000-4000-8000-100000000011', '00000000-0000-4000-8000-b00000000001', 0.500,   18.00, 3.5,  74.0),
  ('00000000-0000-4000-8000-100000000011', '00000000-0000-4000-8000-b00000000002', 5.000,   18.00, 3.5,  74.0)
on conflict (log_id, product_id) do nothing;

-- ---------------------------------------------------------------------------
-- A short starting history.
--
-- Inserted like any other event — through the trigger, which assigns the
-- sequence and the digest — so the seeded chain verifies rather than being a
-- special case the verification has to excuse. Without it the Audit Manager's
-- change history is empty on a fresh database, which shows the empty state
-- rather than the feature.
-- ---------------------------------------------------------------------------
with m as (
  select id, org_id, display_name, role from public.members order by role, display_name
),
admin as (select * from m where role = 'admin' limit 1),
mgr   as (select * from m where role = 'manager' limit 1),
-- Each event names the row it is actually about. An event that says
-- "Glyphosate" against a record holding Urea is worse than no seed at all: the
-- first thing anyone does with a history panel is check it against the record
-- beside it.
picks as (
  select
    (select id from public.products where name ilike 'Glyphosate%' limit 1) as glyphosate,
    a.id          as first_app,
    a.rate        as first_rate,
    p.name        as first_product,
    p.rate_unit   as first_unit,
    a.log_id      as first_app_log,
    (select id from public.recordings where log_id = a.log_id limit 1) as first_app_rec
  from public.applications a
  join public.products p on p.id = a.product_id
  order by a.created_at
  limit 1
)
insert into public.audit_events
  (org_id, actor_id, actor_label, action, entity_type, entity_id, summary, changes, created_at)
select * from (
  values
    ((select org_id from admin), (select id from admin), (select display_name from admin),
     'create'::public.audit_action, 'product', (select glyphosate from picks),
     'Added Glyphosate 41% to the product register',
     '{"Kind":{"from":null,"to":"chemical"},"Re-entry interval (hours)":{"from":null,"to":12}}'::jsonb,
     now() - interval '38 days'),
    ((select org_id from mgr), (select id from mgr), (select display_name from mgr),
     'create'::public.audit_action, 'application', (select first_app from picks),
     'Filed ' || (select first_product from picks) || ' at ' ||
       trim(trailing '.' from trim(trailing '0' from (select first_rate from picks)::text)) ||
       ' ' || (select first_unit from picks),
     jsonb_build_object('Rate', jsonb_build_object('from', null, 'to', (select first_rate from picks))),
     now() - interval '12 days'),
    ((select org_id from mgr), (select id from mgr), (select display_name from mgr),
     'update'::public.audit_action, 'recording', (select first_app_rec from picks),
     'Corrected a transcript',
     '{"Transcript":{"from":"side dressed with urea","to":"Side-dressed with urea"}}'::jsonb,
     now() - interval '11 days'),
    -- `actor_id` null is the ingestion pipeline rather than a person, and the
    -- trail says so in words rather than leaving a blank.
    ((select org_id from admin), null, 'Automated ingestion',
     'create'::public.audit_action, 'log', (select first_app_log from picks),
     'Created a log from a voice recording',
     '{"Status":{"from":null,"to":"new"}}'::jsonb,
     now() - interval '9 days')
) as v(org_id, actor_id, actor_label, action, entity_type, entity_id, summary, changes, created_at);


-- ---------------------------------------------------------------------------
-- The demo's clock.
--
-- Two of the seeded logs are re-dated relative to `now()` so the restricted
-- entry story is live whenever this is loaded rather than only on the day it
-- was written:
--
--   * Benjamin's pest-control pass on FIELD K ran this morning. Sulfur DF
--     carries a 24-hour re-entry interval, so the block is closed for the rest
--     of today — the safety item at the top of the triage queue.
--   * Liam's pre-plant burndown on FIELD C ran yesterday evening. Glyphosate's
--     12-hour interval has since elapsed, so that block reads as clear. Having
--     one of each is the point: a dashboard where every field is red teaches
--     people to ignore red.
--
-- The burndown is deliberately filed without an acreage — a real application
-- nobody measured — so the Pesticide Use Report has something to exclude and a
-- reason to say so at the foot of the file.
-- ---------------------------------------------------------------------------
update public.activity_logs
set started_at = date_trunc('hour', now()) - interval '4 hours',
    ended_at   = date_trunc('hour', now()) - interval '2 hours'
where id = '00000000-0000-4000-8000-100000000011';

update public.activity_logs
set started_at = date_trunc('hour', now()) - interval '22 hours',
    ended_at   = date_trunc('hour', now()) - interval '19 hours'
where id = '00000000-0000-4000-8000-100000000003';

insert into public.applications (log_id, product_id, rate, area_acres, wind_speed_mph, air_temp_f)
select '00000000-0000-4000-8000-100000000003', id, 1.5, null, 4.0, 66
from public.products where name ilike 'Glyphosate%'
on conflict (log_id, product_id) do update set area_acres = null;
